import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

class GapTests(unittest.TestCase):
    def check(self, worked, opening):
        return find_gaps([parse_span(text) for text in worked], parse_span(opening))

    def test_gap_in_the_middle(self):
        self.assertEqual(
            self.check(["09:00-12:00", "13:00-17:00"], "09:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_edges(self):
        self.assertEqual(
            self.check(["10:00-11:00"], "09:00-12:00"),
            ["gap 09:00-10:00 (60 min)", "gap 11:00-12:00 (60 min)"]
        )

    def test_overlaps_leave_no_gap(self):
        self.assertEqual(self.check(["09:00-13:00", "12:00-17:00"], "09:00-17:00"), [])

    def test_nobody_working(self):
        self.assertEqual(self.check([], "09:00-10:00"), ["gap 09:00-10:00 (60 min)"])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            self.check(["08:00-12:00"], "09:00-17:00")
        with self.assertRaises(ValueError):
            self.check(["12:00-18:00"], "09:00-17:00")

if __name__ == "__main__":
    unittest.main()
